            name: "Exact Funder",
            kind: "Funder",
            funder_kind: "Company",
            match_source: { kind: "name" },
          },
        ],
      },
    }),
  );
  await context.route("**/api/members/*", (route) =>
    route.fulfill({ json: memberDetails }),
  );
